-- SQLite schema of a 3AX-UI 1.8.1 database, generated by running that release's
-- database.InitDB (branch backup/dev-before-upstream-sync). Used to test the 1.x migration.
CREATE TABLE `awg_clients` (`id` integer PRIMARY KEY AUTOINCREMENT,`server_id` integer,`uuid` text,`name` text,`email` text,`enable` numeric DEFAULT true,`comment` text,`private_key` text,`public_key` text,`preshared_key` text,`ipv4_address` text,`ipv6_address` text,`allowed_ips` text,`client_allowed_ips` text DEFAULT "0.0.0.0/0,::/0",`forwarded_ports` text DEFAULT "",`persistent_keepalive` integer DEFAULT 25,`upload` integer DEFAULT 0,`download` integer DEFAULT 0,`total_gb` integer DEFAULT 0,`all_time` integer DEFAULT 0,`last_peer_up` integer DEFAULT 0,`last_peer_down` integer DEFAULT 0,`expiry_time` integer DEFAULT 0,`reset` integer DEFAULT 0,`limit_ip` integer DEFAULT 0,`tg_id` integer DEFAULT 0,`last_online` integer DEFAULT 0,`last_ip` text DEFAULT "",`created_at` integer,`updated_at` integer);
CREATE TABLE `awg_servers` (`id` integer PRIMARY KEY AUTOINCREMENT,`enable` numeric DEFAULT false,`interface_name` text DEFAULT "awg0",`listen_port` integer DEFAULT 51820,`mtu` integer DEFAULT 1420,`private_key` text,`public_key` text,`ipv4_address` text DEFAULT "10.66.66.1/24",`ipv4_pool` text DEFAULT "10.66.66.0/24",`ipv6_enabled` numeric DEFAULT false,`ipv6_address` text,`ipv6_pool` text,`ipv6_gateway` text,`jc` integer DEFAULT 4,`jmin` integer DEFAULT 50,`jmax` integer DEFAULT 1000,`s1` integer DEFAULT 0,`s2` integer DEFAULT 0,`s3` integer DEFAULT 0,`s4` integer DEFAULT 0,`h1` text DEFAULT "1",`h2` text DEFAULT "2",`h3` text DEFAULT "3",`h4` text DEFAULT "4",`i1` text DEFAULT "",`dns_ipv4` text DEFAULT "1.1.1.1",`dns_ipv6` text DEFAULT "2606:4700:4700::1111",`external_interface` text DEFAULT "",`ipv6_external_interface` text DEFAULT "",`post_up` text,`post_down` text,`endpoint` text,`traffic_reset` text DEFAULT "never",`route_via_xray` numeric DEFAULT false,`xray_inbound_tag` text DEFAULT "awg-tproxy-in",`xray_tproxy_port` integer DEFAULT 12345,`created_at` integer,`updated_at` integer);
CREATE TABLE `client_traffics` (`id` integer PRIMARY KEY AUTOINCREMENT,`inbound_id` integer,`enable` numeric,`email` text,`up` integer,`down` integer,`all_time` integer,`expiry_time` integer,`total` integer,`reset` integer DEFAULT 0,`last_online` integer DEFAULT 0,CONSTRAINT `fk_inbounds_client_stats` FOREIGN KEY (`inbound_id`) REFERENCES `inbounds`(`id`),CONSTRAINT `uni_client_traffics_email` UNIQUE (`email`));
CREATE TABLE `custom_geo_resources` (`id` integer PRIMARY KEY AUTOINCREMENT,`geo_type` text NOT NULL,`alias` text NOT NULL,`url` text NOT NULL,`local_path` text,`last_updated_at` integer DEFAULT 0,`last_modified` text,`created_at` integer,`updated_at` integer);
CREATE TABLE `history_of_seeders` (`id` integer PRIMARY KEY AUTOINCREMENT,`seeder_name` text);
CREATE TABLE `inbound_client_ips` (`id` integer PRIMARY KEY AUTOINCREMENT,`client_email` text,`ips` text,CONSTRAINT `uni_inbound_client_ips_client_email` UNIQUE (`client_email`));
CREATE TABLE `inbounds` (`id` integer PRIMARY KEY AUTOINCREMENT,`user_id` integer,`up` integer,`down` integer,`total` integer,`all_time` integer DEFAULT 0,`remark` text,`enable` numeric,`expiry_time` integer,`traffic_reset` text DEFAULT "never",`last_traffic_reset_time` integer DEFAULT 0,`listen` text,`port` integer,`protocol` text,`settings` text,`stream_settings` text,`tag` text,`sniffing` text,`public_port` integer DEFAULT 0,CONSTRAINT `uni_inbounds_tag` UNIQUE (`tag`));
CREATE TABLE `mtproto_clients` (`id` integer PRIMARY KEY AUTOINCREMENT,`inbound_id` integer,`uuid` text,`email` text,`enable` numeric,`secret` text,`comment` text,`sub_id` text,`upload` integer DEFAULT 0,`download` integer DEFAULT 0,`all_time` integer DEFAULT 0,`total_gb` integer DEFAULT 0,`expiry_time` integer DEFAULT 0,`reset` integer DEFAULT 0,`limit_ip` integer DEFAULT 0,`tg_id` integer DEFAULT 0,`last_online` integer DEFAULT 0,`created_at` integer,`updated_at` integer);
CREATE TABLE `outbound_traffics` (`id` integer PRIMARY KEY AUTOINCREMENT,`tag` text,`up` integer DEFAULT 0,`down` integer DEFAULT 0,`total` integer DEFAULT 0,CONSTRAINT `uni_outbound_traffics_tag` UNIQUE (`tag`));
CREATE TABLE `settings` (`id` integer PRIMARY KEY AUTOINCREMENT,`key` text,`value` text);
CREATE TABLE `stub_sites` (`id` integer PRIMARY KEY AUTOINCREMENT,`name` text,`html` text,`active` numeric,`size` integer,`created_at` integer,`updated_at` integer);
